require __DIR__.'/../../app/bootstrap.php';require_once __DIR__.'/../../app/api_v1.php';if(!setting_bool('mobile_api_enabled',true))api_json(['ok'=>false,'error'=>'Mobile API is disabled'],503);$u=api_user();api_scope($u,'catalog');$type=(string)($_GET['type']??'products');if($type==='businesses'){$rows=db()->query("SELECT b.id,b.name,b.slug,b.address,b.phone,b.verification_status,c.name city_name FROM businesses b LEFT JOIN cities c ON c.id=b.city_id WHERE b.status=1 ORDER BY b.featured DESC,b.id DESC LIMIT 100")->fetchAll();}elseif($type==='cities'){$rows=db()->query('SELECT id,name,slug FROM cities ORDER BY name')->fetchAll();}else{$rows=store_products([],100);}api_json(['ok'=>true,'type'=>$type,'data'=>$rows]);